#include "bsp_led.h"
#include "main.h"   /* LED1_Pin / LED1_GPIO_Port, generated by CubeMX */

void bsp_led_set(bsp_led_t led, bool cmd)
{
    switch (led) {
    case BSP_LED_GREEN:
        HAL_GPIO_WritePin(LED_GREEN_GPIO_Port, LED_GREEN_Pin, cmd ? GPIO_PIN_SET : GPIO_PIN_RESET);
        break;
    case BSP_LED_YELLOW:
        HAL_GPIO_WritePin(LED_YELLOW_GPIO_Port, LED_YELLOW_Pin, cmd ? GPIO_PIN_SET : GPIO_PIN_RESET);
        break;
    case BSP_LED_RED:
        HAL_GPIO_WritePin(LED_RED_GPIO_Port, LED_RED_Pin, cmd ? GPIO_PIN_SET : GPIO_PIN_RESET);
        break;
    default:
        break;
    }
}